// Package totp is the TOTP second factor of the authentication capability: the
// one factor kind whose code is generated by the user's own authenticator app
// from a seed this module holds.
//
// It delivers authn.Factor for the kind totp. It does no orchestration of its
// own: registration, the failure back-off, the audit row and the event are the
// multi-factor module's, which drives this factor through the root package's
// Factor interface. What this module does is generate a seed, seal it, hand
// back the otpauth address once, and check a code against the seed with the
// replay protection the library's own validation does not give.
//
// The seed is a secret: it is written into an encrypted column and read back
// through a model, it never reaches a log line, an error text, an event or a
// metric, and the otpauth address that carries it is answered once and never
// read again.
package totp

import (
	"context"
	"embed"
	"fmt"
	"io/fs"

	"github.com/vislake/speed/pkg/authn"
	"github.com/vislake/speed/pkg/authn/internal/clock"
	"github.com/vislake/speed/pkg/config"
	"github.com/vislake/speed/pkg/core"
	"github.com/vislake/speed/pkg/db"
)

// ModuleName is this module's name in the registry. A host writes it into the
// command whose users register a TOTP factor.
const ModuleName = "authn.mfa.totp"

// ConfigNamespace is where this module's input items are mounted, which is the
// module name.
const ConfigNamespace = ModuleName

//go:embed migrations
var migrationRoot embed.FS

// migrationsFS is migrationRoot with the wrapping directory removed, so that the
// tree the database module sees has one directory per dialect at its root.
var migrationsFS = func() fs.FS {
	sub, err := fs.Sub(migrationRoot, "migrations")
	if err != nil {
		// The embed directive above makes this unreachable: the directory is
		// part of the source tree or the build fails first.
		panic(ModuleName + ": the embedded migration tree: " + err.Error())
	}
	return sub
}()

// init registers this module with the process registry. Importing the package is
// what puts the TOTP factor in a binary's available set.
func init() { core.ProcessRegistry.Register(Module()) }

// The factor must deliver what the descriptor declares.
var _ authn.Factor = (*factor)(nil)

// Module is the descriptor a host registers.
//
// The factor capability is delivered without claiming it, so several kinds stand
// side by side and the multi-factor module takes them all. The database the seed
// table is in and the multi-factor module that drives this factor are required:
// a factor without its orchestrator is useless, so the drive fails at resolution
// rather than leaving an assembly in which no second factor can be checked. The
// multi-factor module delivers its capability exclusively, so the closure of a
// command that names this one does not pull it in: the host writes it down.
//
// The stance is StateEnabled: a module a drive includes has to start, so a
// configuration it cannot run on is an error from Prepare.
func Module() core.Module {
	return core.Module{
		Name: ModuleName,
		Requires: []core.Requirement{
			{Token: (*db.Database)(nil)},
			{Token: (*authn.MFA)(nil)},
		},
		Provides: []core.Provision{
			{Token: (*authn.Factor)(nil)},
		},
		Resources: []any{schema(), db.Migrations{FS: migrationsFS}},

		Prepare: func(_ context.Context, reg *core.Registry) (core.Enablement, error) {
			reader, err := readerOf(reg)
			if err != nil {
				return core.Enablement{}, err
			}
			if _, err := readConfig(reader); err != nil {
				return core.Enablement{}, err
			}
			return core.Enablement{State: core.StateEnabled}, nil
		},

		// New reads no table of its own: this stage runs before the migrations
		// are applied, so on a first start the table is not there yet.
		New: func(_ context.Context, reg *core.Registry) (any, error) {
			return newFactor(reg)
		},

		Start: func(ctx context.Context, _ *core.Registry, instance any) error {
			f, ok := factorOf(instance)
			if !ok {
				return nil
			}
			return f.start(ctx)
		},

		Stop:  func(context.Context, *core.Registry, any) error { return nil },
		Close: func(context.Context, *core.Registry, any) error { return nil },
	}
}

// factorOf narrows an instance to this module's product. The callbacks are also
// handed an instance a host supplied for the module, which can be any value that
// delivers the capability; they act on the module's own product and leave a
// supplied one as it is.
func factorOf(instance any) (*factor, bool) {
	f, ok := instance.(*factor)
	return f, ok && f != nil
}

// readerOf takes up the configuration reader. Its absence is the host's omission
// and is carried out as it stands, not read as "nothing was configured".
func readerOf(reg *core.Registry) (config.Reader, error) {
	reader, err := core.Resolve[config.Reader](reg)
	if err != nil {
		return nil, fmt.Errorf("%s: the issuer is read from configuration and no reader was handed to the "+
			"registry before the assembly began: %w", ModuleName, err)
	}
	return reader, nil
}

// newFactor takes up what the descriptor requires and assembles the factor. The
// multi-factor module is resolved and not held: this factor is driven by it and
// never calls it, and the resolve is what fails an assembly that took this
// factor without the orchestrator.
func newFactor(reg *core.Registry) (*factor, error) {
	reader, err := readerOf(reg)
	if err != nil {
		return nil, err
	}
	cfg, err := readConfig(reader)
	if err != nil {
		return nil, err
	}
	database, err := core.Resolve[db.Database](reg)
	if err != nil {
		return nil, fmt.Errorf("%s: taking up the database: %w", ModuleName, err)
	}
	if _, err := core.Resolve[authn.MFA](reg); err != nil {
		return nil, fmt.Errorf("%s: taking up the multi-factor module: %w", ModuleName, err)
	}
	return &factor{
		register: &register{handle: database.DB()},
		issuer:   cfg.issuer,
		clock:    clock.Now,
	}, nil
}

// start runs in Start: the table must be there, and the encrypted column must
// round-trip, which is how an assembly with no usable root key is refused now
// and not at the first enrollment.
func (f *factor) start(ctx context.Context) error {
	if err := f.register.probe(ctx); err != nil {
		return err
	}
	if err := f.register.roundTrip(ctx); err != nil {
		return fmt.Errorf("%w: %s: %w", authn.ErrNoEncryptionKey, ModuleName, err)
	}
	return nil
}
